#include <stdio.h>

#define INF 1000000000

int main() {
    int N, M;
    scanf("%d %d", &N, &M);

    int g[105][105];
    for (int i = 1; i <= N; i++) {
        for (int j = 1; j <= N; j++) {
            g[i][j] = (i == j) ? 0 : INF;
        }
    }

    for (int i = 0; i < M; i++) {
        int A, B, C;
        scanf("%d %d %d", &A, &B, &C);
        if (C < g[A][B]) {
            g[A][B] = C;
            g[B][A] = C;
        }
    }

    int dist[105];
    int used[105] = {0};

    for (int i = 1; i <= N; i++) {
        dist[i] = INF;
    }
    dist[1] = 0;

    for (int i = 1; i <= N; i++) {
        int v = -1;
        int best = INF;

        for (int j = 1; j <= N; j++) {
            if (!used[j] && dist[j] < best) {
                best = dist[j];
                v = j;
            }
        }

        if (v == -1) break;
        used[v] = 1;

        for (int u = 1; u <= N; u++) {
            if (g[v][u] < INF && dist[v] + g[v][u] < dist[u]) {
                dist[u] = dist[v] + g[v][u];
            }
        }
    }

    printf("%d\n", dist[N]);

    return 0;
}
